-- Этап B, пачка 3/7 — сводка отзывов на основе веб-поиска.

update public.institutions set
  feedback_summary_student = 'Хвалят компетентных преподавателей по профильным дисциплинам (метеорология, гидрология, экология), повышенные стипендии и практики в Даймище. Значительная критика — устаревшие методы преподавания, проблемы с бытом в общежитиях (сантехника, отопление), заметное сокращение полевых практик — исторической «фишки» классических специальностей.',
  feedback_positive_highlights = '{"сильные профильные дисциплины (метеорология, гидрология, экология)","повышенные стипендии","практики в Даймище"}',
  feedback_negative_highlights = '{"устаревшие методы преподавания","бытовые проблемы в общежитиях","сокращение полевых практик"}',
  feedback_based_on_count = 6, feedback_generated_at = now(), updated_at = now()
where name = 'Российский государственный гидрометеорологический университет' and city = 'Санкт-Петербург';

update public.institutions set
  feedback_summary_student = 'Один из ведущих педагогических вузов страны: высокий стандарт преподавания, сильный состав преподавателей (кандидаты и доктора наук), честная система оценивания. Основная критика — организационные проблемы деканата на некоторых факультетах и неудобное расписание там, где набирают много платных студентов (особенно факультет иностранных языков).',
  feedback_positive_highlights = '{"сильный, остепенённый состав преподавателей","честная система оценивания без взяток","широкий спектр дисциплин и научная работа"}',
  feedback_negative_highlights = '{"организационные проблемы деканата на отдельных факультетах","неудобное расписание при большом числе платных студентов"}',
  feedback_based_on_count = 5, feedback_generated_at = now(), updated_at = now()
where name = 'Российский государственный педагогический университет им. А.И. Герцена' and city = 'Санкт-Петербург';

update public.institutions set
  feedback_summary_student = 'Старейший театральный вуз страны (с 1779 года), обучение построено на системе мастерских с выходом на сцену собственного Учебного театра «На Моховой». Найденные прямые отзывы студентов немногочисленны, но положительны («учусь с большим удовольствием»). Развёрнутого негативного паттерна в открытых источниках не нашёл.',
  feedback_positive_highlights = '{"обучение через практику в собственном учебном театре","старейшая театральная школа страны с сильными традициями"}',
  feedback_negative_highlights = '{}',
  feedback_based_on_count = 1, feedback_generated_at = now(), updated_at = now()
where name = 'Российский государственный институт сценических искусств' and city = 'Санкт-Петербург';

update public.institutions set
  feedback_summary_student = 'Отзывы неоднородны и сильно зависят от инициативности студента. Плюсы: профессионализм и культура общения преподавателей, широкая гуманитарная программа (философия, литература, история), возможность рано включиться в науку (конференции, публикации). Заметная критика — распад отдельных кафедр из-за ухода квалифицированных преподавателей, формальное отношение к части студентов.',
  feedback_positive_highlights = '{"широкая гуманитарная программа","ранняя вовлечённость студентов в науку","профессионализм части преподавателей"}',
  feedback_negative_highlights = '{"отток квалифицированных преподавателей с отдельных кафедр","формальное/безразличное отношение к части студентов"}',
  feedback_based_on_count = 5, feedback_generated_at = now(), updated_at = now()
where name = 'Русская христианская гуманитарная академия им. Ф. М. Достоевского' and city = 'Санкт-Петербург';

update public.institutions set
  feedback_summary_student = 'Хорошая репутация в фармацевтической отрасли: диплом признаётся не только в РФ, но и за рубежом, актуальная программа, заинтересованные в передаче знаний преподаватели. Заметная и частая критика — навязанная покупка дорогих учебных пособий издательства вуза, устаревшее лабораторное оборудование, небольшие стипендии.',
  feedback_positive_highlights = '{"диплом признаётся в РФ и за рубежом","актуальная учебная программа","заинтересованные преподаватели"}',
  feedback_negative_highlights = '{"навязанная покупка платных учебных пособий","устаревшее оборудование в лабораториях","небольшие стипендии"}',
  feedback_based_on_count = 51, feedback_generated_at = now(), updated_at = now()
