update public.institutions set
  feedback_summary_student = 'Молодая (с 2016 года) ведомственная академия с сильной бытовой поддержкой: бесплатное проживание и питание, качественный преподавательский состав, много возможностей для развития (спорт, творчество). Отзывы отмечают отдельные организационные и технические проблемы, требующие от студента гибкости и терпения.',
  feedback_positive_highlights = '{"бесплатное проживание и питание","качественный преподавательский состав","развитая внеучебная жизнь"}',
  feedback_negative_highlights = '{"отдельные организационные и технические проблемы"}',
