update public.institutions set
  feedback_summary_student = 'Отзывы преимущественно критические. Основная жалоба — формальный характер практики (после 3 курса специалитета студенты в суде «разбирают бумажки», а не наблюдают за процессом). Отдельно отмечено требование к студентам писать положительные отзывы, чтобы «топить» негативные — сигнал о недостаточной прозрачности. Из плюсов — красивое расположение (Александровский парк) и помощь сотрудников по отдельным вопросам.',
  feedback_positive_highlights = '{"живописное расположение здания","отзывчивость части сотрудников по отдельным вопросам"}',
  feedback_negative_highlights = '{"формальный, не содержательный характер практики","давление на студентов с целью получения положительных отзывов","резкие изменения расписания без предупреждения"}',
  feedback_based_on_count = 4, feedback_generated_at = now(), updated_at = now()
where name = 'Северо-Западный филиал Российского государственного университета правосудия имени В. М. Лебедева' and city = 'Санкт-Петербург';

update public.institutions set
  feedback_summary_student = 'Отзывы смешанные. Плюсы: строгая дисциплина, требовательные преподаватели, хорошее трудоустройство выпускников. Минусы — заметные: изношенное здание, отсутствие собственной спортивной базы и нормальной столовой (только дорогое кафе), у части абитуриентов есть подозрение, что места распределены заранее вне зависимости от баллов ЕГЭ.',
  feedback_positive_highlights = '{"строгая дисциплина и требовательность","хорошее трудоустройство выпускников в таможенную сферу"}',
  feedback_negative_highlights = '{"изношенное здание, отсутствие своей спортивной базы","подозрения в предопределённости мест при поступлении"}',
  feedback_based_on_count = 4, feedback_generated_at = now(), updated_at = now()
where name = 'Санкт-Петербургский имени В.Б. Бобкова филиал Российской таможенной академии' and city = 'Санкт-Петербург';

